<?php require_once __DIR__.'/chart_local.php'; function fsplot(){$resource="SELECT COUNT(*),fstype,COUNT(DISTINCT site.name) FROM site WHERE last_activity>=DATE_SUB(NOW(),INTERVAL 2 MONTH) AND status=1 AND fstype NOT IN ('','-') GROUP BY fstype ORDER BY COUNT(*) DESC";$r=db_query($resource,'ro');$d=[];$s=[];while($x=mysqli_fetch_row($r)){$d[]=[$x[1],(float)$x[0]];$s[]=[$x[1],(float)$x[2]];}echo '<div id="fschart_div">'.atlas_chart_pie($d,'FileSystem Types (active resources)').'</div>';echo '<div id="fssitechart_div">'.atlas_chart_pie($s,'FileSystem Types (active sites)').'</div>';}
